INSERT INTO `j34_mymuse_store` (`id`, `title`, `name`, `alias`, `scope`, `description`, `published`, `checked_out`, `checked_out_time`, `ordering`, `access`, `count`, `params`, `currency`, `version`, `metadesc`, `metakey`, `metadata`, `my_catid`, `state`) VALUES
(1, 'Sing Song Inc', '', 'sing-song-inc', 'store', '<p><strong>SingSong Inc</strong>. is a Newfoundland and Labrador recording company owned and operated by performing artist <a href=\"index.php?option=com_mymuse&amp;view=category&amp;layout=blog&amp;id=18&amp;Itemid=7\">Jim Payne</a>. It was started in 1989, and is dedicated to traditional and contemporary music, story, song and dance that reflect the Newfoundland experience. The label has 27 currently available titles, making it the largest dedicated traditional music label in the province.</p>\r\n<p><strong>SingSong Inc.</strong> also produces special event entertainment for conferences, conventions, corporate retreats, and other events with a particular interest in historical music related to Newfoundland and Labrador. For several years we produced a <em>Music at the Museum</em> summer concert series for museums in St. John\'s, Grand Bank and Grand Falls-Windsor, in conjunction with the Newfoundland Museum and the Historic Resources Division of the Department of Tourism and Culture. Over the years, <strong>SingSong Inc.</strong> has also been a sponsor of several regular performance events in St. John\'s, including the <a href=\"http://nlfolk.com/folkclub/folkclub.html\">St. John\'s Folk Music Club</a>, produced by the <a href=\"http://nlfolk.com/\">Folk Arts Society</a>, and Wom/men Jammin\'. We\'ve also produced recorded music for use in the Parks Canada Ryan\'s Premises Historic Site in Bonavista, and co-produced recordings with the Historic Sites Association of Newfoundland and Labrador. We\'ve also co-produced recordings of Newfoundland and Labrador artists in collaboration with artists in England and Ireland for simultaneous release on both sides of the Atlantic.</p>\r\n<p>All audio recordings listed on the site can be downloaded either as individual tracks or full CDs. Full CD downloads also include cover art and liner notes.&nbsp;Besides standard format CDs,&nbsp;<strong>SingSong Inc. </strong>has also released a CD-ROM collection of 517 Newfoundland folk songs (included in the catalogue) collected by Canadian folk song enthusiast Kenneth Peacock around the coast of Newfoundland in the 1950\'s. This collection includes many of Mr. Peacock\'s original audio recordings of his informants, some of the first recordings ever made of traditional Newfoundland folk songs.</p>\r\n<p>Watch for other projects currently in development, including song and music books, DVDs, as well as new recordings on CD. Explore the site to find information about new releases and the full catalogue of recordings, along with information about artists and &nbsp;CD reviews.&nbsp;</p>\r\n<p>Many of the <strong>SingSong Inc.</strong> artists are also available for live performances, and all titles in the catalogue are in stock and available. Contact us by e-mail, phone or regular mail for details on live performances or to order recordings in hard copy.</p>', 1, 0, '0000-00-00 00:00:00', 1, 0, 0, '{\"contact_first_name\":\"Jim\",\"contact_last_name\":\"Payne\",\"contact_title\":\"\",\"contact_email\":\"gord@arboreta.ca\",\"phone\":\"514 484-8333\",\"fax\":\"514 484-8333\",\"address_1\":\"Box 6371\",\"address_2\":\"\",\"city\":\"St. John\'s\",\"province\":\"NL\",\"country\":\"CA\",\"zip\":\"A1C 6J9\",\"twitter_handle\":\"\",\"currency\":\"CAD\",\"store_thumb_image\":\"images\\/stories\\/logosm2.jpg\",\"my_downloads_enable\":\"1\",\"my_formats\":[\"mp3\"],\"my_download_max\":\"3\",\"my_download_expire\":\"432000\",\"my_download_enable_status\":\"C\",\"my_download_dir\":\"\\/var\\/www\\/html\\/singsong\\/images\\/A_MyMuseDownloads\",\"my_download_dir_format\":\"0\",\"my_use_zip\":\"1\",\"my_preview_dir\":\"images\\/A_MyMusePreviews\",\"my_previews_in_one_dir\":\"0\",\"my_encode_filenames\":\"0\",\"my_use_string_url_safe\":\"1\",\"my_use_shipping\":\"1\",\"my_add_shipping_auto\":\"0\",\"my_use_stock\":\"0\",\"my_check_stock\":\"0\",\"my_add_stock_zero\":\"0\",\"my_saveorder\":\"before\",\"my_currency_separator\":\",\",\"my_currency_dec_point\":\".\",\"my_currency_position\":\"0\",\"my_registration_redirect\":\"login\",\"my_registration\":\"full\",\"my_noreg_password\":\"buyer\",\"my_checkout\":\"regular\",\"my_profile_key\":\"mymuse\",\"my_use_coupons\":\"0\",\"my_use_alias\":\"0\",\"top_menu_item\":\"4\",\"my_show_cart_preview\":\"0\",\"my_show_cart_player\":\"0\",\"my_disable_css\":\"0\",\"my_plugin_email\":\"0\",\"my_cc_webmaster\":\"1\",\"my_webmaster\":\"info@arboreta.ca\",\"my_webmaster_name\":\"Gord Fisch\",\"my_continue_shopping\":\"index.php\",\"my_date_format\":\"Y-m-d H:i:s\",\"my_default_itemid\":\"\",\"my_email_msg\":\"\",\"my_max_recommended\":\"4\",\"my_show_original_price\":\"0\",\"my_show_category_name\":\"1\",\"my_show_sku\":\"0\",\"my_default_shopper_group_id\":\"1\",\"my_price_by_product\":\"0\",\"my_ownergid\":\"1\",\"my_owner_percent\":\"100\",\"my_shop_test\":\"0\",\"my_debug\":\"1\"}', 'CAD', '2.5.0', '', '', '{\"robots\":\"\",\"author\":\"\",\"rights\":\"\",\"xreference\":\"\"}', 16, 1);
